import java.util.*;

public class CourseSchedule {
    public boolean canFinish(int numCourses, int[][] prerequisites) {
        // 建图：b → a，a 的入度 +1
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < numCourses; i++) graph.add(new ArrayList<>());
        int[] indegree = new int[numCourses];
        for (int[] p : prerequisites) {
            graph.get(p[1]).add(p[0]);  // 先修指向后续
            indegree[p[0]]++;
        }
        // 入度为 0 的课程先入队
        Deque<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < numCourses; i++) {
            if (indegree[i] == 0) queue.offer(i);
        }
        int learned = 0;
        while (!queue.isEmpty()) {
            int course = queue.poll();
            learned++;
            for (int next : graph.get(course)) {
                if (--indegree[next] == 0) queue.offer(next);
            }
        }
        return learned == numCourses;
    }
}

import java.util.*;

public class CourseScheduleDFS {
    public boolean canFinish(int numCourses, int[][] prerequisites) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < numCourses; i++) graph.add(new ArrayList<>());
        for (int[] p : prerequisites) graph.get(p[1]).add(p[0]);

        int[] visited = new int[numCourses]; // 0:白, 1:灰, 2:黑
        for (int i = 0; i < numCourses; i++) {
            if (visited[i] == 0 && hasCycle(graph, visited, i)) {
                return false;
            }
        }
        return true;
    }

    private boolean hasCycle(List<List<Integer>> graph, int[] visited, int node) {
        visited[node] = 1;  // 进栈：白→灰
        for (int next : graph.get(node)) {
            if (visited[next] == 1) return true;   // 灰→灰 = 回边 = 环
            if (visited[next] == 0 && hasCycle(graph, visited, next)) return true;
        }
        visited[node] = 2;  // 出栈：灰→黑
        return false;
    }
}
